    def from_tree(tree_dict):
        """
        Creates a zipper from a dictionary-based binary tree, focusing on the root node.
        The input `tree_dict` is expected to be a dictionary like
        `{"value": N, "left": L_SUBTREE, "right": R_SUBTREE}` or None for empty.
        """
        # Convert the dictionary-based tree to our internal Node structure
        node_tree = Zipper._dict_to_node(tree_dict)
        return Zipper(node_tree, None)

