        new_context_item = ParentContext(
            value=self._focus.value,
            sibling=self._focus.left,  # The left child becomes the sibling
            direction='R',             # We moved to the right
            parent_context=self._context
        )
        return Zipper(self._focus.right, new_context_item)

    def set_right(self, new_right_tree_dict):
        """
        Sets the right child of the focus node, returns a new zipper.
        `new_right_tree_dict` is expected to be a dictionary-based tree or None.
        """
        # Convert the new right subtree from dictionary to Node format
        new_right_node = Zipper._dict_to_node(new_right_tree_dict)
        new_focus = Node(self._focus.value, self._focus.left, new_right_node)
        return Zipper(new_focus, self._context)

    def up(self):
        """Moves the focus to the parent, returns a new zipper or None if at the root."""
        if not self._context:
            return None  # Already at the root, no parent

        parent_ctx = self._context

        # Reconstruct the parent node based on the context
        if parent_ctx.direction == 'L':
            # Current focus was the left child of its parent
            reconstructed_parent = Node(
                value=parent_ctx.value,
                left=self._focus,          # Current focus is the parent's left child
                right=parent_ctx.sibling    # Sibling stored in context is parent's right child
