            # Current focus was the right child of its parent
            reconstructed_parent = Node(
                value=parent_ctx.value,
                left=parent_ctx.sibling,    # Sibling stored in context is parent's left child
                right=self._focus           # Current focus is the parent's right child
            )

        # The new focus is the reconstructed parent, and its context is the grandparent's context
        return Zipper(reconstructed_parent, parent_ctx.parent_context)

    def to_tree(self):
        """
        Climbs up the tree until the root is reached and returns the full
        reconstructed binary tree in dictionary format.
        """
        current_zipper = self
        while current_zipper._context:
            current_zipper = current_zipper.up()

        # After climbing up, current_zipper._focus is the root Node object.
        # Convert it back to the dictionary format expected by the tests.
        return Zipper._node_to_dict(current_zipper._focus)
